const assetPathPrefix = "https://www.figma.com/api/mcp/asset/93e3efef-aa04-4b88-a03c-d0ab20102ec5";
const imgLucideChevronRight = `${assetPathPrefix}/265fe.svg`;
const imgLucideChevronLeft = `${assetPathPrefix}/a5b62.svg`;
const imgLucideEllipsis = `${assetPathPrefix}/3c7f5.svg`;
const imgLucidePawPrint = `${assetPathPrefix}/cf295.svg`;

type MDMobileV2ActionProps = {
  className?: string;
  label?: string;
  style?: "Primary" | "Quiet";
};

function MDMobileV2Action({ className, label = "主要操作", style = "Primary" }: MDMobileV2ActionProps) {
  const isQuiet = style === "Quiet";
  return (
    <div className={className || `content-stretch flex h-[48px] items-center px-[var(--mnd-study-space-16,16px)] relative rounded-[var(--mnd-mobile-button-radius,24px)] ${isQuiet ? "w-[88px]" : "bg-[var(--mnd-button-study-primary,#c84b3d)] justify-center w-[96px]"}`} id={isQuiet ? "node-56_181" : "node-56_179"}>
      {style === "Primary" && (
        <p className="[word-break:break-word] flex-[1_0_0] font-['Noto_Sans_SC:Medium'] font-medium leading-[24px] min-w-px relative text-[16px] text-[color:var(--mnd-button-study-onPrimary,#fffefc)] text-center" data-node-id="56:184">
          {label}
        </p>
      )}
      {isQuiet && (
        <p className="[word-break:break-word] flex-[1_0_0] font-['Noto_Sans_SC:Medium'] font-medium leading-[22px] min-w-px relative text-[14px] text-[color:var(--mnd-button-study-quiet,#9e382a)]" data-node-id="56:186">
          {label}
        </p>
      )}
    </div>
  );
}

type MDMobileV2ListRowProps = {
  className?: string;
  title?: string;
  value?: string;
};

function MDMobileV2ListRow({ className, title = "列表名称", value = "当前值或下一步" }: MDMobileV2ListRowProps) {
  return (
    <div className={className || "content-stretch flex gap-[var(--mnd-study-space-8,8px)] h-[64px] items-center min-h-[64px] relative w-[326px]"} data-node-id="56:214" data-name="M&D Mobile V2 / List row">
      <div className="[word-break:break-word] content-stretch flex flex-[1_0_0] flex-col font-['Noto_Sans_SC:Regular'] font-normal gap-[var(--mnd-study-space-4,4px)] items-start min-w-px overflow-clip relative" data-node-id="56:215" data-name="Row copy">
        <p className="leading-[26px] relative shrink-0 text-[16px] text-[color:var(--mnd-study-color-ink,#202329)] w-full" data-node-id="56:216">
          {title}
        </p>
        <p className="leading-[20px] relative shrink-0 text-[12px] text-[color:var(--mnd-study-color-muted,#616771)] w-full" data-node-id="56:217">
          {value}
        </p>
      </div>
      <div className="content-stretch flex flex-col gap-[var(--mnd-study-space-8,8px)] items-start relative shrink-0 size-[20px]" data-node-id="56:218" data-name="Instance / icon/chevron-right">
        <div className="relative shrink-0 size-[24px]" data-node-id="I56:218;56:140" data-name="Lucide / chevron-right">
          <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgLucideChevronRight} />
        </div>
      </div>
    </div>
  );
}

